                Phone2 = "+90 533 140 56 49",
                WhatsApp = "905394624149",
                Email = "info@akinelotoyedekparca.com.tr",
                Address = "Osmangazi Mh. Tuzla Cd. No:238/B",
                District = "Darıca",
                City = "Kocaeli",
                Country = "Türkiye",
                PostalCode = "41700",
                GoogleMapsUrl = "https://www.google.com/maps/dir//AKINEL+OTO+YEDEK+PAR%C3%87A,+Osman+Gazi,+Tuzla+Cd.+No:238%2FB,+41700+Dar%C4%B1ca%2FKocaeli/@40.7793666,29.3758179,17z",
                GoogleMapsEmbedUrl = "https://maps.google.com/maps?q=AKINEL+OTO+YEDEK+PARCA+Darica+Kocaeli&output=embed&hl=tr",
                WebsiteUrl = "https://akinelotoyedekparca.com.tr",
            };
            context.BusinessSettings.Add(biz);
            await context.SaveChangesAsync();

            context.BusinessWorkingHours.AddRange(
                new BusinessWorkingHour { BusinessSettingsId = bizId, DayOfWeek = 0, IsOpen = false },
                new BusinessWorkingHour { BusinessSettingsId = bizId, DayOfWeek = 1, IsOpen = true, OpenTime = "09:00", CloseTime = "19:00" },
                new BusinessWorkingHour { BusinessSettingsId = bizId, DayOfWeek = 2, IsOpen = true, OpenTime = "09:00", CloseTime = "19:00" },
                new BusinessWorkingHour { BusinessSettingsId = bizId, DayOfWeek = 3, IsOpen = true, OpenTime = "09:00", CloseTime = "19:00" },
                new BusinessWorkingHour { BusinessSettingsId = bizId, DayOfWeek = 4, IsOpen = true, OpenTime = "09:00", CloseTime = "19:00" },
                new BusinessWorkingHour { BusinessSettingsId = bizId, DayOfWeek = 5, IsOpen = true, OpenTime = "09:00", CloseTime = "19:00" },
                new BusinessWorkingHour { BusinessSettingsId = bizId, DayOfWeek = 6, IsOpen = true, OpenTime = "09:00", CloseTime = "19:00" }
            );
            await context.SaveChangesAsync();
        }

        // Sync vehicle make logos & IsPopular from B2 (runs on every deploy, idempotent)
        var logoMap = new Dictionary<string, string>
        {
            ["audi"]          = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/d5f62b4a-c758-4a2c-b1b2-5d08b8059658.webp",
            ["bmw"]           = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/702dcd5b-59d8-47e0-9bc4-a1f05a1127c1.webp",
            ["citroen"]       = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/c67668e6-117a-4341-915a-b5d15c27fb90.webp",
            ["fiat"]          = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/c03967b4-a99d-4235-9ffd-e92fd02fcfdd.webp",
            ["ford"]          = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/ab6f6b46-cd6a-4dbb-9d19-bb1a0b3ada1d.webp",
            ["honda"]         = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/2e99b61e-1ca0-4d2c-a00c-644251b6cbf0.webp",
            ["hyundai"]       = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/bbf4e117-cd41-4bd3-ad7e-89e6150a2995.webp",
            ["mercedes-benz"] = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/290da447-c727-4df1-8e8a-d08be5503463.webp",
            ["opel"]          = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/9454e1af-5d74-48ca-830f-4999c6d38eec.webp",
            ["peugeot"]       = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/d45544af-fc12-4f0f-9fc3-db5010925133.webp",
            ["renault"]       = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/76d08d36-4448-4b7e-97ab-2b7314fe3334.webp",
            ["toyota"]        = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/ed5a471a-59b8-4de9-94e6-dd3d502f8fad.webp",
            ["volkswagen"]    = "https://akinel-uploads.s3.eu-central-003.backblazeb2.com/uploads/vehicle-makes/318143a8-a712-4c2c-a205-1a32dece11a0.webp",
        };
        var popularSlugs = new HashSet<string> { "audi", "bmw", "citroen", "fiat", "ford", "honda", "hyundai", "mercedes-benz", "opel", "peugeot", "renault", "toyota", "volkswagen" };
        var makesToPatch = await context.VehicleMakes
            .Where(m => logoMap.Keys.Contains(m.Slug))
            .ToListAsync();
        foreach (var make in makesToPatch)
        {
            if (logoMap.TryGetValue(make.Slug, out var logo)) make.LogoUrl = logo;
            make.IsPopular = popularSlugs.Contains(make.Slug);
        }
        if (makesToPatch.Count > 0) await context.SaveChangesAsync();

        if (await context.Brands.AnyAsync()) return;

        var brands = new List<Brand>
        {
            new() { Name = "Bosch", Slug = "bosch" },
            new() { Name = "Valeo", Slug = "valeo" },
            new() { Name = "SKF", Slug = "skf" },
            new() { Name = "Delphi", Slug = "delphi" },
            new() { Name = "TRW", Slug = "trw" },
        };
        context.Brands.AddRange(brands);

        var catBrakes = new Category { Name = "Fren Sistemi", Slug = "fren-sistemi" };
        var catClutch = new Category { Name = "Debriyaj", Slug = "debriyaj" };
        var catFilters = new Category { Name = "Filtreler", Slug = "filtreler" };
        var catSuspension = new Category { Name = "Süspansiyon", Slug = "suspansiyon" };
        var catElectrical = new Category { Name = "Elektrik Sistemi", Slug = "elektrik-sistemi" };
        var catCooling = new Category { Name = "Soğutma Sistemi", Slug = "sogutma-sistemi" };
        context.Categories.AddRange(catBrakes, catClutch, catFilters, catSuspension, catElectrical, catCooling);

        var subBrakePads = new Category { Name = "Fren Balatası", Slug = "fren-balatasi", ParentCategory = catBrakes };
        var subBrakeDiscs = new Category { Name = "Fren Diski", Slug = "fren-diski", ParentCategory = catBrakes };
        var subAbsSensors = new Category { Name = "ABS Sensörleri", Slug = "abs-sensorleri", ParentCategory = catBrakes };
        var subOilFilter = new Category { Name = "Yağ Filtresi", Slug = "yag-filtresi", ParentCategory = catFilters };
        var subAirFilter = new Category { Name = "Hava Filtresi", Slug = "hava-filtresi", ParentCategory = catFilters };
        context.Categories.AddRange(subBrakePads, subBrakeDiscs, subAbsSensors, subOilFilter, subAirFilter);

        // Sample products
        var bosch = brands[0];
        var trw = brands[4];
        var p1 = new Product { Name = "Arka Fren Balata Seti", Slug = "arka-fren-balata-seti-bosch", BrandId = bosch.Id, CategoryId = subBrakePads.Id, PartNumber = "0986424706", Price = 850.00m };
        var p2 = new Product { Name = "Ön Fren Diski", Slug = "on-fren-diski-trw", BrandId = trw.Id, CategoryId = subBrakeDiscs.Id, PartNumber = "DF4101", Price = 1200.00m };
        var p3 = new Product { Name = "Yağ Filtresi", Slug = "yag-filtresi-bosch", BrandId = bosch.Id, CategoryId = subOilFilter.Id, PartNumber = "P3370", Price = 120.00m };
        context.Products.AddRange(p1, p2, p3);
        await context.SaveChangesAsync();

        context.Stocks.AddRange(
            new Stock { ProductId = p1.Id, Quantity = 50, ReservedQuantity = 0, MinimumStockLevel = 5 },
            new Stock { ProductId = p2.Id, Quantity = 30, ReservedQuantity = 2, MinimumStockLevel = 5 },
            new Stock { ProductId = p3.Id, Quantity = 100, ReservedQuantity = 0, MinimumStockLevel = 10 }
        );

        var oem1 = new OemNumber { Number = "0986424706", NormalizedNumber = "0986424706", Manufacturer = "Bosch" };
        context.OemNumbers.Add(oem1);
        await context.SaveChangesAsync();
        context.ProductOemNumbers.Add(new ProductOemNumber { ProductId = p1.Id, OemNumberId = oem1.Id });

        // Admin user
        if (!await context.Users.AnyAsync(u => u.Email == "admin@akinel.com"))
        {
            var adminPassword = Environment.GetEnvironmentVariable("AKINEL_ADMIN_PASSWORD") ?? "Admin123!";
            context.Users.Add(new User
            {
                Email = "admin@akinel.com",
                NormalizedEmail = "ADMIN@AKINEL.COM",
                PasswordHash = BCrypt.Net.BCrypt.HashPassword(adminPassword),
                FirstName = "Admin",
                LastName = "User",
                Role = UserRole.Admin,
                IsActive = true
            });
        }

        await SeedVehiclesAsync(context);
        await context.SaveChangesAsync();
    }

